descriptor.templateCss:
.isa101-widget-card { width:100%; height:100%; background:#E5E7EB; border-radius:8px; border:1px solid #CBD5E1; display:flex; flex-direction:column; align-items:center; justify-content:space-between; padding:8px; box-sizing:border-box; font-family:sans-serif; }
.isa101-widget-title { font-size:11px; font-weight:700; color:#334155; text-align:center; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; width:100%; }
@keyframes isaAlarmPulse { 0%, 100% { border-color: #CBD5E1; } 50% { border-color: #DC2626; } }
.isa-alarm-pulse { animation: isaAlarmPulse 1.2s ease-in-out infinite; border-width: 2px; }

descriptor.controllerScript:
self.onInit = function() {
    var s = self.ctx.settings || {};
    self.ctx.$scope.title = s.title || (self.ctx.widget && self.ctx.widget.config && self.ctx.widget.config.title) || "Ventilateur / Extracteur";
    self.ctx.$scope.unit = s.unit || "";
    self.ctx.$scope.decimals = s.decimals !== undefined ? Number(s.decimals) : 1;
    self.ctx.$scope.accentColor = s.accentColor || "#475569";
    self.ctx.$scope.valDisplay = "--";
    self.ctx.$scope.isAlarm = false;
    self.ctx.$scope.fillPct = 50;
    self.ctx.$scope.statusColor = self.ctx.$scope.accentColor;
    self.onDataUpdated();
};

self.onDataUpdated = function() {
    var s = self.ctx.settings || {};
    var val = null;
    var unit = s.unit || "";
    if (self.ctx.data && self.ctx.data.length > 0) {
        var ds = self.ctx.data[0];
        if (!unit && ds.dataKey && ds.dataKey.units) {
            unit = ds.dataKey.units;
        }
        if (ds.data && ds.data.length > 0) {
            val = ds.data[ds.data.length - 1][1];
        }
    }
    if (val !== null && val !== undefined) {
        var num = Number(val);
        if (!isNaN(num)) {
            var dec = s.decimals !== undefined ? Number(s.decimals) : 1;
            self.ctx.$scope.valDisplay = num.toFixed(dec) + (unit ? " " + unit : "");
            self.ctx.$scope.fillPct = Math.max(0, Math.min(100, num));
            var c = s.accentColor || "#475569";
            var alarm = false;
            if (s.critThreshold !== undefined && s.critThreshold !== null && s.critThreshold !== "" && num >= Number(s.critThreshold)) {
                c = "#DC2626";
                alarm = true;
            } else if (s.warnThreshold !== undefined && s.warnThreshold !== null && s.warnThreshold !== "" && num >= Number(s.warnThreshold)) {
                c = "#D97706";
            }
            self.ctx.$scope.statusColor = c;
            self.ctx.$scope.isAlarm = alarm;
        } else {
            self.ctx.$scope.valDisplay = String(val);
            var isFault = (val === true || val === "true" || val === "ALARM" || val === "FAULT");
            self.ctx.$scope.statusColor = isFault ? "#DC2626" : "#475569";
            self.ctx.$scope.isAlarm = isFault;
        }
    }
    self.ctx.detectChanges();
};
